module argmax(input wire signed [31:0] logit0,logit1,logit2,logit3,logit4,logit5,logit6,logit7,logit8,logit9,output reg [3:0] index); reg signed [31:0] v[0:9]; reg signed [31:0] best; integer i; always @* begin v[0]=logit0;v[1]=logit1;v[2]=logit2;v[3]=logit3;v[4]=logit4;v[5]=logit5;v[6]=logit6;v[7]=logit7;v[8]=logit8;v[9]=logit9; best=v[0]; index=0; for(i=1;i<10;i=i+1) if(v[i]>best) begin best=v[i]; index=i; end end endmodule
